// cambc bot: runs the embedded grammar policy (policy_data.h, generated by bot/sync.sh) with
// the same interpreter the simulator uses (interp/src/policy.cpp, vendored), over a
// bot-side cbs::Api backed by the engine's imports (bot_api.cpp).
#include <cambc.h>
#include <cstdio>
#include <exception>
#include "bot_api.h"
#include "cbs/api.h"
#include "cbs/coro.h"
#include "interp/policy.h"
#include "policy_data.h"

namespace interp { long long prof_fuel(); }
long long interp::prof_fuel() { return cambc::detail::sdk_fuel_remaining(); }
int main()
{
	using namespace cambc::detail;
	const int team = sdk_my_team();
	const int champ = cambc::is_draft() ? -1 : sdk_my_champion();
	auto mp = cbs::build_map_from_engine();
	static cbs::Game game(mp);
	cbs::board_rows = mp->H; // all boards live inside the map
	static cbs::Api api(game, team, champ);
	api.count_charges = false; // the engine meters real fuel
	static cbs::Coroutine yielder;
	api.attach(&yielder); // api.end_turn() -> engine end_turn
	std::shared_ptr<const interp::Program> prog;
	try
	{
		prog = interp::load_program_codes(kPolicyCode, sizeof kPolicyCode / sizeof *kPolicyCode, kPolicyNums, kPolicyNumCount, kPolicyBytes, kPolicyBytesCount);
	}
	catch (const std::exception& e)
	{
		std::printf("policy load failed: %s\n", e.what());
		for (;;) cambc::end_turn();
	}
	auto player = interp::make_policy_player(prog, 0x5eed0000u + static_cast<unsigned>(team * 64 + champ + 1));
	cbs::BotBody body = player->make_bot(team, champ);
	for (;;)
	{
		try
		{
			body(api); // loops forever: one policy pass per turn, then api.end_turn()
		}
		catch (const std::exception& e)
		{
			std::printf("bot error: %s\n", e.what());
		}
		catch (...)
		{
			std::printf("bot error: unknown exception\n");
		}
		cambc::end_turn();
	}
}
